-- Core tests: spans, questions, decode, policy.
--
-- These deliberately do NOT require('jev.actions'): the catalogs below are
-- inline so the pure-Lua core can be tested on its own. The three-action
-- catalog and the "find three test files in the git changed stuff" utterance
-- are the worked example from the research notes, generated by running the
-- reference questions.js/decode.js — every id, wording and probability below
-- is copied from that run.

local spans = require('jev.spans')
local questions = require('jev.questions')
local decode = require('jev.decode')
local policy = require('jev.policy')

--------------------------------------------------------------------------------
-- Inline catalogs
--------------------------------------------------------------------------------

--- The research notes' worked example, as JevAction entries.
local worked = {
  {
    name = 'goto_definition',
    description = 'Jump to the definition of the symbol under the cursor.',
    readOnly = true,
    params = {},
    run = function() end,
  },
  {
    name = 'find_files',
    description = 'Fuzzy-find files in the project by name.',
    readOnly = true,
    params = {
      query = { type = 'string', required = true, description = 'Text to match against file paths' },
      scope = {
        type = 'enum',
        description = 'Where to search',
        enum = { project = '', open_buffers = '', git_changed = '' },
      },
      limit = { type = 'integer', description = 'How many results', min = 1, max = 10 },
    },
    run = function() end,
  },
  {
    name = 'split_window',
    description = 'Split the current window.',
    params = {
      direction = { type = 'enum', required = true, enum = { horizontal = '', vertical = '' } },
      focus = { type = 'boolean', description = 'move the cursor into the new window' },
    },
    run = function() end,
  },
}

--- Same three plus an unbounded integer, a destructive action and a set.
local wider = vim.list_extend({}, worked)
vim.list_extend(wider, {
  {
    name = 'goto_line',
    description = 'Move the cursor to a line.',
    readOnly = true,
    params = { line = { type = 'integer', required = true, description = 'Line number' } },
    run = function() end,
  },
  {
    name = 'quit_all',
    description = 'Close every window and quit.',
    destructive = true,
    params = {},
    run = function() end,
  },
  {
    name = 'show_diagnostics',
    description = 'List diagnostics in the quickfix window.',
    readOnly = true,
    params = {
      severity = { type = 'array', description = 'Which levels to show', enum = { error = '', warn = '', hint = '' } },
    },
    run = function() end,
  },
})

local UTTERANCE = 'find three test files in the git changed stuff'

--- The 19 spans the reference implementation produces for UTTERANCE, in order.
local WORKED_SPANS = {
  'find', 'three', 'test', 'files', 'git', 'changed', 'stuff',
  'find three', 'three test', 'test files', 'git changed', 'changed stuff',
  'find three test', 'three test files', 'git changed stuff',
  'find three test files', 'files in the git',
  'test files in the git', 'files in the git changed',
}

local function keys_of(tbl)
  local keys = {}
  for k in pairs(tbl or {}) do
    keys[#keys + 1] = k
  end
  table.sort(keys)
  return keys
end

local function noul(value)
  return { type = 'noul', noul = value }
end

local function choice(picked, probabilities, confidence)
  return { type = 'choice', choice = picked, probabilities = probabilities, confidence = confidence }
end

--------------------------------------------------------------------------------
-- spans.lua
--------------------------------------------------------------------------------

describe('spans.spans', function()
  it("lifts the user's own words, never starting or ending on a function word", function()
    -- Straight from the reference test suite (test/core.test.js).
    local found = spans.spans('find me some oat milk under $5?')
    ok(vim.tbl_contains(found, 'oat milk'), 'expected "oat milk"')
    ok(vim.tbl_contains(found, '$5'), 'expected "$5"')
    ok(not vim.tbl_contains(found, 'me'), '"me" is an edge stopword')
    ok(not vim.tbl_contains(found, 'some oat milk'), '"some" is an edge stopword')
    for _, s in ipairs(found) do
      ok(not s:find('%?$'), 'no span may keep trailing punctuation: ' .. s)
    end
  end)

  it('returns shortest first and keeps interior stopwords', function()
    eq(spans.spans(UTTERANCE), WORKED_SPANS)
  end)

  it('dedupes case-insensitively but keeps the original casing', function()
    eq(spans.spans('Test test'), { 'Test', 'Test test' })
  end)

  it('has nothing to say about an empty utterance', function()
    eq(spans.spans(''), {})
    eq(spans.spans('the a of to'), {}, 'all edge stopwords')
  end)

  it('caps the candidate list', function()
    local many = {}
    for i = 1, 200 do
      many[i] = 'word' .. i
    end
    eq(#spans.spans(table.concat(many, ' ')), 120, 'capped at 120, under the API 255-option limit')
  end)
end)

describe('spans.numbers', function()
  it('parses digits, words, compounds and phrases in code', function()
    eq(spans.numbers('two cartons and 3.5 lbs, under twenty five bucks'), {
      { value = 2, text = 'two' },
      { value = 3.5, text = '3.5' },
      { value = 25, text = 'twenty five' },
    })
    eq(spans.numbers('half a dozen eggs'), { { value = 6, text = 'half a dozen' } })
    eq(spans.numbers('a couple of limes and a dozen eggs'), {
      { value = 2, text = 'a couple of' },
      { value = 12, text = 'a dozen' },
    })
    eq(spans.numbers('no numbers here'), {})
  end)

  it('handles hyphenated tens and rejects overlaps', function()
    eq(spans.numbers('line twenty-one'), { { value = 21, text = 'twenty-one' } })
    -- "half a dozen" claims its span, so the trailing "a dozen" cannot also match.
    eq(#spans.numbers('half a dozen'), 1)
  end)

  it('dedupes by value, keeping the first mention', function()
    eq(spans.numbers('three files and three more'), { { value = 3, text = 'three' } })
  end)

  it('finds the number in the worked example', function()
    eq(spans.numbers(UTTERANCE), { { value = 3, text = 'three' } })
  end)
end)

