-- policy.lua
--------------------------------------------------------------------------------

describe('policy.decide', function()
  local built = questions.build(worked, UTTERANCE)
  local wider_built = questions.build(wider, UTTERANCE)

  local function call_for(overrides, catalog, meta)
    return decode.decode(catalog or worked, worked_answers(overrides), meta or built.meta)
  end

  it('auto: read-only and confident', function()
    local call = call_for({
      ['find_files::query'] = choice('test files', { ['test files'] = 0.9 }),
    })
    near(call.confidence, 0.88, 1e-9)
    eq(policy.decide(call), 'auto')
    eq(policy.decide(call, { live = false }), 'ready', 'no live mode means no auto')
  end)

  it('ready: read-only but under the auto threshold', function()
    local call = call_for()
    near(call.confidence, 0.71, 1e-9)
    eq(policy.decide(call), 'ready')
  end)

  it('ready: a state-changing action never auto-runs, however confident', function()
    local call = call_for({
      ['__tool__'] = choice('split_window', { split_window = 0.99 }),
      ['split_window::direction'] = choice('vertical', { vertical = 0.99, horizontal = 0.01 }),
      ['split_window::focus'] = noul(0.01),
    })
    near(call.confidence, 0.99, 1e-9)
    eq(policy.decide(call), 'ready')
  end)

  it('confirm: a destructive action always asks, however confident', function()
    local call = decode.decode(wider, {
      ['__tool__'] = choice('quit_all', { quit_all = 0.99 }),
    }, wider_built.meta)
    near(call.confidence, 0.99)
    eq(policy.decide(call), 'confirm')
  end)

  it('confirm: below the confirm threshold', function()
    local call = call_for({
      ['__tool__'] = choice('split_window', { split_window = 0.9 }),
    })
    near(call.confidence, 0.5, 1e-9, 'a 50/50 direction')
    eq(policy.decide(call), 'confirm')
  end)

  it('confirm: a flagged catalog never auto-runs', function()
    local call = call_for({ ['find_files::query'] = choice('test files', { ['test files'] = 0.9 }) })
    eq(policy.decide(call, { flagged = true }), 'confirm')
  end)

  it('incomplete: a required argument has no value yet', function()
    local call = call_for({ ['find_files::query'] = choice('(not stated)', { ['(not stated)'] = 0.9 }) })
    eq(policy.decide(call), 'incomplete')
  end)

  it('none: no action, or a route under the route threshold', function()
    eq(policy.decide(nil), 'none')
    eq(policy.decide(call_for({ ['__tool__'] = choice('__none__', { ['__none__'] = 0.99 }) })), 'none')
    eq(policy.decide(call_for({ ['__tool__'] = choice('find_files', { find_files = 0.3 }) })), 'none', 'route < 0.5')
  end)

  it('order of evaluation: missing beats destructive beats read-only', function()
    local incomplete = decode.decode(wider, {
      ['__tool__'] = choice('goto_line', { goto_line = 0.99 }),
    }, questions.build(wider, 'move down').meta)
    eq(incomplete.missing, { 'line' })
    eq(policy.decide(incomplete), 'incomplete', 'a missing argument outranks the read-only auto path')
  end)

  it('uses the documented default thresholds and lets them be overridden', function()
    eq(policy.DEFAULTS, { route = 0.5, auto = 0.8, confirm = 0.6 })
    local call = call_for()
    eq(policy.decide(call, { thresholds = { auto = 0.7 } }), 'auto', 'confidence 0.71 clears a 0.7 auto bar')
    eq(policy.decide(call, { thresholds = { confirm = 0.75 } }), 'confirm')
    eq(policy.decide(call, { thresholds = { route = 0.99 } }), 'none', 'route 0.97 under a 0.99 bar')
  end)
end)

--------------------------------------------------------------------------------
-- Serialization
--------------------------------------------------------------------------------

describe('questions JSON', function()
  it('round-trips, with every Choice criteria as a JSON object', function()
    local built = questions.build(worked, UTTERANCE)
    local encoded = vim.json.encode(built.questions)

    ok(not encoded:find('"criteria":[', 1, true), 'no criteria may encode as a JSON array')

    local back = vim.json.decode(encoded)
    eq(keys_of(back), {
      '__tool__',
      'find_files::limit',
      'find_files::limit?',
      'find_files::query',
      'find_files::scope',
      'find_files::scope?',
      'split_window::direction',
      'split_window::focus',
    })
    eq(back['__tool__'].type, 'choice')
    eq(back['__tool__'].criteria.find_files, 'Fuzzy-find files in the project by name.')
    eq(back['find_files::query'].criteria['test files'], vim.NIL, 'a null-described option stays null')
    eq(back['find_files::query'].criteria['(not stated)'], 'The request does not say this.')
    eq(keys_of(back['find_files::scope'].criteria), { 'git_changed', 'open_buffers', 'project' })
    eq(back['find_files::scope?'].type, 'noul')
    eq(back['find_files::scope?'].criteria, nil, 'a bare Noul carries no criteria')

    for id, question in pairs(back) do
      if question.type == 'choice' then
        ok(type(question.criteria) == 'table', id .. ' criteria must decode as a table')
        ok(#question.criteria == 0, id .. ' criteria must be an object, not an array')
        ok(next(question.criteria) ~= nil, id .. ' criteria must not be empty')
      end
    end
  end)

  it('encodes empty criteria as {} and not []', function()
    local built = questions.build({
      { name = 'odd', description = 'An action with an empty option set.', params = { pick = { type = 'enum', required = true, enum = {} } } },
    }, 'hi')
    local encoded = vim.json.encode(built.questions)
    ok(encoded:find('"criteria":{}', 1, true), 'expected an empty JSON object: ' .. encoded)
  end)

  it('encodes the whole request body the client will POST', function()
    local built = questions.build(worked, UTTERANCE)
    local body = vim.json.encode({ state = built.meta.state, model = 'jev-latest', questions = built.questions })
    local back = vim.json.decode(body)
    eq(back.state, UTTERANCE)
    eq(back.model, 'jev-latest')
    eq(back.questions['__tool__'].instructions, "Which action does the user's request call for?")
  end)
end)
